import React, { useState, useEffect, useRef } from 'react';
import { 
  Container, Box, Typography, Alert, CircularProgress,
  Divider, Accordion, AccordionSummary, AccordionDetails,
  Button, Grid, Paper, useTheme
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import TimelineIcon from '@mui/icons-material/Timeline';
import DashboardIcon from '@mui/icons-material/Dashboard';
import CodeIcon from '@mui/icons-material/Code';
import TerminalIcon from '@mui/icons-material/Terminal';
import ChatIcon from '@mui/icons-material/Chat';

import Header from '../Layout/Header';
import ConversationInput from '../Conversation/ConversationInput';
import ConversationChunk from '../Conversation/ConversationChunk';
import SummaryStats from '../Analysis/SummaryStats';
import ComplaintTrackingChart from '../Analysis/ComplaintTrackingChart';
import ConversationDetail from '../Conversation/ConversationDetail';
import ConversationUpload from '../Conversation/ConversationUpload';
import PageHeader from '../Layout/PageHeader';

import { 
  parseConversation, 
  chunkConversation, 
  calculateComplaintPercentage 
} from '../../utils/conversationParser';
import { predictionService, authService } from '../../services/api';

// Create a cyberpunk styled section container
const CyberpunkSection = ({ title, icon, children }) => {
  return (
    <Paper
      elevation={0}
      sx={{
        position: 'relative',
        borderRadius: 2,
        overflow: 'hidden',
        backgroundColor: 'rgba(10, 2, 5, 0.95)',
        backdropFilter: 'none',
        color: 'var(--neon-green)',
        border: '2px solid var(--neon-green)',
        boxShadow: '0 0 15px rgba(0, 255, 65, 0.5)',
        height: '100%',
        display: 'flex',
        flexDirection: 'column'
      }}
    >
      <Box 
        sx={{ 
          display: 'flex', 
          alignItems: 'center', 
          p: 1.5, 
          borderBottom: '1px solid var(--dark-green)',
          background: 'linear-gradient(90deg, rgba(0,20,0,0.8) 0%, rgba(0,40,0,0.4) 100%)',
        }}
      >
        <Box sx={{ 
          mr: 1, 
          color: 'var(--neon-green)', 
          display: 'flex' 
        }}>
          {icon}
        </Box>
        <Typography 
          variant="h6" 
          sx={{ 
            fontFamily: 'monospace', 
            textTransform: 'uppercase',
            letterSpacing: '0.1em',
            fontSize: '1.2rem',
            fontWeight: 'bold',
            textShadow: '0 0 5px var(--neon-green)',
            color: 'var(--text-color)'
          }}
        >
          {title}
        </Typography>
      </Box>
      <Box sx={{ 
        flex: 1, 
        p: 2,
      }}>
        {children}
      </Box>
    </Paper>
  );
};

// Create a real-time tracker component (floating)
const RealTimeTracker = ({ chunks, onClose }) => {
  const chartRef = useRef(null);
  const [chartData, setChartData] = useState([]);

  useEffect(() => {
    if (chunks && chunks.length > 0) {
      // Convert chunks to time-series data for the chart
      const timeSeriesData = chunks.map((chunk, index) => ({
        timestamp: new Date(chunk.timestamp || Date.now()),
        confidence: chunk.confidence * 100,
        isComplaint: chunk.isComplaint,
        chunkId: chunk.id || `chunk-${index}`
      }));

      // Sort by timestamp
      const sortedData = timeSeriesData.sort((a, b) => a.timestamp - b.timestamp);
      setChartData(sortedData);
    }
  }, [chunks]);

  return (
    <Paper 
      elevation={3} 
      sx={{ 
        position: 'fixed', 
        bottom: 20, 
        right: 20, 
        width: 350, 
        height: 300, 
        p: 0,
        zIndex: 1000,
        display: 'flex',
        flexDirection: 'column',
        border: '1px solid var(--neon-green)',
        boxShadow: '0 0 20px rgba(0, 255, 65, 0.4)',
        background: 'rgba(13, 2, 8, 0.9)',
        backdropFilter: 'none',
        overflow: 'hidden'
      }}
    >
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        p: 1.5,
        borderBottom: '1px solid var(--dark-green)',
        background: 'linear-gradient(90deg, rgba(0,20,0,0.8) 0%, rgba(0,40,0,0.4) 100%)',
      }}>
        <Typography 
          variant="h6" 
          sx={{ 
            display: 'flex', 
            alignItems: 'center',
            fontFamily: 'monospace',
            fontSize: '0.9rem',
            textTransform: 'uppercase'
          }}
        >
          <TimelineIcon sx={{ mr: 1, color: 'var(--neon-green)' }} /> 
          Real-time Tracking
        </Typography>
        <Button 
          variant="text" 
          size="small" 
          onClick={onClose}
          sx={{
            color: 'var(--neon-green)',
            '&:hover': {
              backgroundColor: 'rgba(0, 255, 65, 0.1)'
            }
          }}
        >
          Close
        </Button>
      </Box>

      <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'auto', p: 2 }}>
        {chartData.length > 0 ? (
          <Box sx={{ height: 200 }} ref={chartRef}>
            {chartData.map((point, index) => (
              <Box key={index} sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                <Typography variant="caption" sx={{ color: 'var(--muted-green)' }}>
                  {point.timestamp.toLocaleTimeString()}
                </Typography>
                <Typography 
                  variant="caption" 
                  sx={{ 
                    color: point.isComplaint ? 'var(--bright-green)' : 'var(--dark-green)',
                    fontWeight: 'bold',
                    textShadow: point.isComplaint ? '0 0 5px var(--neon-green)' : 'none'
                  }}
                >
                  {point.confidence.toFixed(1)}% {point.isComplaint ? '(Complaint)' : '(No Complaint)'}
                </Typography>
              </Box>
            ))}
          </Box>
        ) : (
          <Typography variant="body2" sx={{ textAlign: 'center', mt: 4, color: 'var(--muted-green)' }}>
            No data available yet. Analyze a conversation to see real-time tracking.
          </Typography>
        )}
      </Box>
    </Paper>
  );
};

const Dashboard = ({ onLogout }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [analyzedData, setAnalyzedData] = useState(null);
  const [expandedChunk, setExpandedChunk] = useState('');
  const [showTracker, setShowTracker] = useState(false);

  const handleExpandChange = (chunkId) => (event, isExpanded) => {
    setExpandedChunk(isExpanded ? chunkId : '');
  };

  // Load user data
  useEffect(() => {
    const fetchUser = async () => {
      const userData = await authService.getUser();
      setUser(userData);
    };

    fetchUser();
  }, []);

  const handleAnalyzeConversation = async (conversationText) => {
    setLoading(true);
    setError('');

    try {
      // Use the new API endpoint to analyze the entire conversation at once
      // Fixed chunk size to 4 as required by the model
      const result = await predictionService.analyzeConversation(conversationText, 4);

      if (result.success) {
        // Convert API response to our format
        const { chunks, complaint_percentage } = result.data;

        // Parse utterances from the whole conversation for display
        const utterances = parseConversation(conversationText);

        // Create our analyzedData object with the API response
        setAnalyzedData({
          utterances,
          chunks: chunks.map(chunk => ({
            id: chunk.id,
            utterances: chunk.utterances,
            text: chunk.text,
            isComplaint: chunk.is_complaint,
            confidence: chunk.confidence,
            timestamp: chunk.timestamp
          })),
          complaintPercentage: complaint_percentage
        });

        // Show the tracker by default
        setShowTracker(true);

        // Expand the first chunk by default
        if (chunks.length > 0) {
          setExpandedChunk(chunks[0].id);
        }
      } else {
        throw new Error(result.error);
      }
    } catch (err) {
      console.error('Analysis error:', err);
      setError(`Failed to analyze conversation: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box className="dashboard-container" sx={{ 
      width: '100%', 
      p: 2,
      color: 'var(--text-color)',
      minHeight: 'calc(100vh - 60px)'
    }}>
      <Grid container spacing={3}>
        <Grid item xs={12}>
          <PageHeader 
            title={<Typography variant="h5" sx={{ ...textStyle, fontSize: '1.8rem', fontWeight: 'bold' }}>Customer Complaint Dashboard</Typography>}
            subtitle="Upload call transcripts, get ML-powered complaint analysis"
          />
        </Grid>

        {/* Conversation Component */}
        <Grid item xs={12}>
          <CyberpunkSection title="Conversation Upload & Analysis">
            <ConversationUpload 
              onConversationAnalyzed={setAnalyzedData} 
              onUploadStarted={() => setAnalyzedData(null)}
            />
          </CyberpunkSection>
        </Grid>

        {/* Only show analysis components when we have data */}
        {analyzedData && (
          <>
            {/* Analysis Summary */}
            <Grid item xs={12}>
              <SummaryStats analyzedData={analyzedData} />
            </Grid>

            {/* Complaint Tracking Chart */}
            <Grid item xs={12}>
              <ComplaintTrackingChart analyzedData={analyzedData} />
            </Grid>

            {/* Full Conversation Display */}
            <Grid item xs={12}>
              <CyberpunkSection title="Full Conversation Analysis">
                <ConversationDetail analyzedData={analyzedData} />
              </CyberpunkSection>
            </Grid>
          </>
        )}
      </Grid>
    </Box>
  );
};

